"use client"

import { AlertCircleIcon, BuildingIcon } from "lucide-react"
import { useEffect, useMemo, useRef, useState } from "react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Spinner } from "@/components/ui/spinner"
import { TabsContent } from "@/components/ui/tabs"
import {
  EMPTY_FACILITY,
  type FacilityValues,
} from "@/components/openlmis/facility-editor-page/facility-form"
import { FacilityGeneralForm } from "@/components/openlmis/facility-editor-page/facility-general-form"
import {
  type FacilityProgram,
  missingStartDate,
} from "@/components/openlmis/facility-editor-page/facility-program"
import { FacilityPrograms } from "@/components/openlmis/facility-editor-page/facility-programs"
import {
  Workspace,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceFooter,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceIcon,
  WorkspaceLayout,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { Callout } from "@/components/openlmis/callout"
import { DiscardChangesDialog } from "@/components/openlmis/discard-changes-dialog"
import { PageBreadcrumbs } from "@/components/openlmis/page-breadcrumbs"
import {
  WorkspaceTabs,
  WorkspaceTabsList,
  WorkspaceTabsTrigger,
} from "@/components/openlmis/workspace-tabs"

import {
  MOCK_FACILITY,
  MOCK_LOOKUPS,
  MOCK_MANAGED_FACILITY,
  MOCK_PROGRAMS,
  MOCK_TAKEN_CODES,
  type MockFacility,
} from "@/components/openlmis/facility-editor-page/mock-facility"

const FORM_ID = "facility-form"

type FacilityTab = "information" | "programs"

type FacilityEditorPageProps = {
  /** Start on a new, empty facility. */
  adding?: boolean
  /** Start on the facility managed by another system. */
  managed?: boolean
  /** Show the skeleton, as while the facility loads. */
  loading?: boolean
  /** Show Save as in progress. */
  pending?: boolean
  /** Mock outcome: every save fails. */
  saveFails?: boolean
  /** Mock outcome: the server refuses any changed code. */
  refuseCodes?: boolean
}

const NEW_FACILITY: MockFacility = {
  values: EMPTY_FACILITY,
  programs: [],
  managedExternally: false,
}

/** Focuses the first invalid field on the open tab, waiting for it to render if needed. */
function focusFirstError(container: HTMLElement) {
  const selector = '[role="tabpanel"]:not([hidden]) [aria-invalid="true"]'
  const focus = () => {
    const field = container.querySelector<HTMLElement>(selector)
    field?.focus()
    return Boolean(field)
  }
  if (focus()) return () => {}
  const observer = new MutationObserver(() => {
    if (focus()) observer.disconnect()
  })
  observer.observe(container, {
    attributes: true,
    attributeFilter: ["aria-invalid", "hidden"],
    childList: true,
    subtree: true,
  })
  return () => observer.disconnect()
}

const programChanges = (
  rows: readonly FacilityProgram[],
  saved: readonly FacilityProgram[]
) => (JSON.stringify(rows) === JSON.stringify(saved) ? 0 : 1)

/** Add or edit a facility on one page: its information, then the programs it supports. */
export function FacilityEditorPage({
  adding: startAdding = false,
  managed = false,
  loading = false,
  pending = false,
  saveFails = false,
  refuseCodes = false,
}: FacilityEditorPageProps) {
  const [adding, setAdding] = useState(startAdding)
  const [saved, setSaved] = useState(
    startAdding ? NEW_FACILITY : managed ? MOCK_MANAGED_FACILITY : MOCK_FACILITY
  )
  // Bumped to start the form again from `saved`, after a save or a discard.
  const [revision, setRevision] = useState(0)
  const [programs, setPrograms] = useState(saved.programs)
  const [tab, setTab] = useState<FacilityTab>("information")
  const [infoChanges, setInfoChanges] = useState(0)
  const [showProgramErrors, setShowProgramErrors] = useState(false)
  const [refusedCodes, setRefusedCodes] = useState<string[]>([])
  const [saveError, setSaveError] = useState(false)
  const [notice, setNotice] = useState<{ title: string; description: string }>()
  const [discarding, setDiscarding] = useState(false)
  // Bumped to focus the first error once the tab holding it is open.
  const [focusRequest, setFocusRequest] = useState(0)
  const container = useRef<HTMLDivElement>(null)

  const locked = saved.managedExternally
  const name = saved.values.name || saved.values.code
  const changes = infoChanges + programChanges(programs, saved.programs)
  const takenCodes = useMemo(
    () => [
      ...MOCK_TAKEN_CODES.filter((code) => code !== saved.values.code),
      ...refusedCodes,
    ],
    [saved.values.code, refusedCodes]
  )

  useEffect(() => {
    if (focusRequest === 0 || !container.current) return
    return focusFirstError(container.current)
  }, [focusRequest])

  const showErrors = (nextTab: FacilityTab) => {
    setTab(nextTab)
    setFocusRequest((current) => current + 1)
  }

  const start = (facility: MockFacility) => {
    setSaved(facility)
    setPrograms(facility.programs)
    setRevision((current) => current + 1)
    setTab("information")
    setInfoChanges(0)
    setShowProgramErrors(false)
    setRefusedCodes([])
    setSaveError(false)
    setNotice(undefined)
  }

  const save = (values: FacilityValues) => {
    setSaveError(false)
    if (programs.some(missingStartDate)) {
      setShowProgramErrors(true)
      showErrors("programs")
      return
    }
    if (saveFails) {
      setSaveError(true)
      return
    }
    if (refuseCodes && values.code !== saved.values.code) {
      // The server refused the code, so the form now marks it as taken.
      setRefusedCodes((codes) => [...codes, values.code])
      showErrors("information")
      return
    }
    const next: MockFacility = {
      ...saved,
      values,
      programs: programs.map((row) => ({ ...row, saved: true })),
    }
    start(next)
    setAdding(false)
    const savedName = values.name || values.code
    setNotice(
      adding
        ? {
            title: "Facility Created",
            description: `${savedName} is ready to use.`,
          }
        : {
            title: "Facility Saved",
            description: `Changes to ${savedName} are saved.`,
          }
    )
  }

  const cancel = () => {
    if (changes > 0) setDiscarding(true)
    else start(saved)
  }

  return (
    <WorkspaceLayout ref={container}>
      <Workspace width="narrow">
        <PageBreadcrumbs
          items={[
            { label: "Home", href: "#" },
            { label: "Administration" },
            { label: "Facilities", href: "#" },
            { label: adding ? "Add Facility" : "Edit Facility" },
          ]}
        />
        <WorkspaceHeader>
          <WorkspaceHeading>
            <WorkspaceIcon>
              <BuildingIcon />
            </WorkspaceIcon>
            <WorkspaceTitle>
              {adding
                ? "Add Facility"
                : loading
                  ? "Edit Facility"
                  : `Edit ${name}`}
            </WorkspaceTitle>
            <WorkspaceDescription>
              {adding
                ? "Set up a facility and the programs it supports."
                : "Change the facility's details and the programs it supports."}
            </WorkspaceDescription>
          </WorkspaceHeading>
        </WorkspaceHeader>
        <WorkspaceContent>
          <div className="flex flex-col gap-4 lg:gap-6" inert={pending}>
            {notice && (
              <Callout title={notice.title} tone="success">
                {notice.description}
              </Callout>
            )}
            {locked && !loading && (
              <Callout title="Managed By Another System" tone="info">
                Its name, code, description, geographic zone and active status
                come from another system, so they cannot be changed here.
              </Callout>
            )}
            {saveError && (
              <Alert variant="destructive">
                <AlertCircleIcon />
                <AlertTitle>Could Not Save Facility</AlertTitle>
                <AlertDescription>
                  Something went wrong. Check your connection and try again.
                </AlertDescription>
              </Alert>
            )}
            <WorkspaceTabs
              onValueChange={(value) => setTab(value as FacilityTab)}
              value={tab}
            >
              <WorkspaceTabsList label="Facility Sections">
                <WorkspaceTabsTrigger value="information">
                  Facility Information
                </WorkspaceTabsTrigger>
                <WorkspaceTabsTrigger value="programs">
                  Associated Programs
                  {!loading && (
                    <Badge variant="secondary">{programs.length}</Badge>
                  )}
                </WorkspaceTabsTrigger>
              </WorkspaceTabsList>
              {/* Kept mounted, so a hidden tab keeps its edits and Save checks both. */}
              <TabsContent keepMounted value="information">
                <FacilityGeneralForm
                  facility={loading ? undefined : saved.values}
                  formId={FORM_ID}
                  goLiveDateRequired={!adding}
                  key={revision}
                  locked={locked}
                  lookups={MOCK_LOOKUPS}
                  onChangesChange={setInfoChanges}
                  onInvalid={() => {
                    // Programs share the submit, so their errors show at once too.
                    setShowProgramErrors(programs.some(missingStartDate))
                    showErrors("information")
                  }}
                  onSubmit={save}
                  takenCodes={takenCodes}
                />
              </TabsContent>
              <TabsContent keepMounted value="programs">
                <FacilityPrograms
                  onRowsChange={setPrograms}
                  programs={MOCK_PROGRAMS}
                  rows={loading ? undefined : programs}
                  showErrors={showProgramErrors}
                />
              </TabsContent>
            </WorkspaceTabs>
          </div>
        </WorkspaceContent>
      </Workspace>
      <WorkspaceFooter width="narrow">
        <Button
          disabled={pending || loading}
          onClick={cancel}
          size="lg"
          variant="outline"
        >
          Cancel
        </Button>
        <Button
          disabled={pending || loading}
          focusableWhenDisabled={pending}
          form={FORM_ID}
          size="lg"
          type="submit"
        >
          {pending && <Spinner data-icon="inline-start" />}
          {adding ? "Create" : "Save"}
        </Button>
      </WorkspaceFooter>
      <DiscardChangesDialog
        changes={changes}
        onDiscard={() => {
          setDiscarding(false)
          start(saved)
        }}
        onKeepEditing={() => setDiscarding(false)}
        open={discarding}
        subject={adding ? "the new facility" : name}
      />
    </WorkspaceLayout>
  )
}

"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { type ReactNode, useMemo } from "react"

import { FieldGroup } from "@/components/ui/field"
import {
  EMPTY_FACILITY,
  facilityFormSchema,
  type FacilityValues,
  toFacilityValues,
} from "@/components/openlmis/facility-editor-page/facility-form"
import {
  type FacilityLookups,
  FacilityFormFields,
} from "@/components/openlmis/facility-editor-page/facility-form-fields"
import { FacilityGeneralFormSkeleton } from "@/components/openlmis/facility-editor-page/facility-general-form"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogError,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"

type FacilityFormDialogProps = {
  open: boolean
  /** The types, zones and operators to pick from; skeletons show until set. */
  lookups: FacilityLookups | undefined
  /** Other facilities' codes, and any the server refused, turned down for the new one. */
  takenCodes?: readonly string[]
  /** Called with trimmed values; create the facility, then close. */
  onSubmit: (values: FacilityValues) => void
  /** Keeps the dialog open and spins Create while the save runs. */
  pending?: boolean
  /** Shown above the fields, e.g. why the create failed; what was typed stays. */
  error?: ReactNode
  onClose: () => void
}

/** Add Facility from a list: its details now, its programs later in the editor. */
export function FacilityFormDialog({
  open,
  pending = false,
  onClose,
  ...props
}: FacilityFormDialogProps) {
  const { shown, dialogProps } = useDialogTarget(open || undefined, onClose)

  return (
    <FormDialog {...dialogProps(pending)}>
      {shown && <AddFacilityContent pending={pending} {...props} />}
    </FormDialog>
  )
}

function AddFacilityHeader() {
  return (
    <FormDialogHeader>
      <FormDialogTitle>Add Facility</FormDialogTitle>
      <FormDialogDescription>
        Set up a facility; add the programs it supports once it is created.
      </FormDialogDescription>
    </FormDialogHeader>
  )
}

type ContentProps = Omit<FacilityFormDialogProps, "open" | "onClose"> & {
  pending: boolean
}

function AddFacilityContent({ lookups, ...props }: ContentProps) {
  if (!lookups) {
    return (
      <>
        <AddFacilityHeader />
        <FormDialogBody>
          <FacilityGeneralFormSkeleton />
        </FormDialogBody>
        <FormDialogFooter>
          <FormDialogCancel />
          <FormDialogSubmit disabled>Create</FormDialogSubmit>
        </FormDialogFooter>
      </>
    )
  }
  return <AddFacilityForm lookups={lookups} {...props} />
}

function AddFacilityForm({
  lookups,
  takenCodes,
  onSubmit,
  pending,
  error,
}: ContentProps & { lookups: FacilityLookups }) {
  const schema = useMemo(() => facilityFormSchema({ takenCodes }), [takenCodes])
  const form = useAppForm({
    defaultValues: EMPTY_FACILITY,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => onSubmit(toFacilityValues(value)),
  })

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <AddFacilityHeader />
      <FormDialogBody>
        <FieldGroup>
          {error && (
            <FormDialogError
              description={error}
              title="Could Not Save Facility"
            />
          )}
          <FacilityFormFields form={form} lookups={lookups} />
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel disabled={pending} />
        <FormDialogSubmit pending={pending}>Create</FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

"use client"

import { useMemo } from "react"

import { withForm } from "@/components/openlmis/form-fields/form"

import {
  EMPTY_FACILITY,
  type FacilityOption,
  toFacilityItems,
} from "@/components/openlmis/facility-editor-page/facility-form"

export type FacilityLookups = {
  types: readonly FacilityOption[]
  zones: readonly FacilityOption[]
  operators: readonly FacilityOption[]
}

type FacilityFormFieldsProps = {
  lookups: FacilityLookups
  /** Managed by another system: name, code, zone, description and Active cannot change. */
  locked?: boolean
  /** Every field read only, e.g. without the right to edit facilities. */
  readOnly?: boolean
  /** A saved facility must keep its operational date. */
  goLiveDateRequired?: boolean
}

/** The facility's details in two columns once there is room, shared by Add Facility and the editor. */
export const FacilityFormFields = withForm({
  defaultValues: EMPTY_FACILITY,
  props: {} as FacilityFormFieldsProps,
  render: function Render({
    form,
    lookups,
    locked = false,
    readOnly = false,
    goLiveDateRequired = false,
  }) {
    const typeItems = useMemo(
      () => toFacilityItems(lookups.types),
      [lookups.types]
    )
    const zoneItems = useMemo(
      () => toFacilityItems(lookups.zones),
      [lookups.zones]
    )
    const operatorItems = useMemo(
      () => toFacilityItems(lookups.operators),
      [lookups.operators]
    )
    const fixed = locked || readOnly

    return (
      <div className="grid gap-x-6 gap-y-5 @3xl/main:grid-cols-2">
        <form.AppField name="name">
          {(field) => (
            <field.TextField
              autoComplete="off"
              dir="auto"
              disabled={fixed}
              label="Facility Name"
              required
            />
          )}
        </form.AppField>
        <form.AppField name="code">
          {(field) => (
            <field.TextField
              autoComplete="off"
              dir="ltr"
              disabled={fixed}
              label="Facility Code"
              required
            />
          )}
        </form.AppField>
        <form.AppField name="typeId">
          {(field) => (
            <field.ComboboxField
              clearLabel="Clear Facility Type"
              disabled={readOnly}
              emptyMessage="No Matches"
              items={typeItems}
              label="Facility Type"
              placeholder="Select A Type"
              required
            />
          )}
        </form.AppField>
        <form.AppField name="zoneId">
          {(field) => (
            <field.ComboboxField
              clearLabel="Clear Geographic Zone"
              disabled={fixed}
              emptyMessage="No Matches"
              items={zoneItems}
              label="Geographic Zone"
              limit={-1}
              placeholder="Select A Zone"
              required
            />
          )}
        </form.AppField>
        <form.AppField name="goLiveDate">
          {(field) => (
            <field.DateField
              clearLabel="Clear Operational Date"
              description="This is used in reporting to record the date the facility becomes operational."
              disabled={readOnly}
              label="Operational Date"
              placeholder="Pick A Date"
              required={goLiveDateRequired}
            />
          )}
        </form.AppField>
        <form.AppField name="operatorId">
          {(field) => (
            <field.ComboboxField
              clearLabel="Clear Facility Operator"
              disabled={readOnly}
              emptyMessage="No Matches"
              items={operatorItems}
              label="Facility Operator"
              placeholder="Select An Operator"
            />
          )}
        </form.AppField>
        <form.AppField name="description">
          {(field) => (
            <field.TextareaField
              dir="auto"
              disabled={fixed}
              label="Description"
            />
          )}
        </form.AppField>
        <div className="@3xl/main:col-start-1">
          <form.AppField name="active">
            {(field) => (
              <field.SwitchField
                description="This determines whether or not the facility can submit requisitions or receive deliveries."
                disabled={fixed}
                label="Active Facility"
              />
            )}
          </form.AppField>
        </div>
        <form.AppField name="enabled">
          {(field) => (
            <field.SwitchField
              description="On: the facility can operate. Off: the facility is permanently decommissioned."
              disabled={readOnly}
              label="Enabled"
            />
          )}
        </form.AppField>
      </div>
    )
  },
})

import { z } from "zod"

/** A facility type, zone or operator: picked by id and shown by name. */
export type FacilityOption = {
  id: string
  name: string
  /** Shown under the name in the list, e.g. a zone's level. */
  description?: string
}

/** What the facility forms show and save; map your API's facility onto it. */
export type FacilityValues = {
  name: string
  code: string
  typeId: string | null
  zoneId: string | null
  /** `yyyy-MM-dd`, or empty for none. */
  goLiveDate: string
  description: string
  operatorId: string | null
  active: boolean
  enabled: boolean
}

export const EMPTY_FACILITY: FacilityValues = {
  name: "",
  code: "",
  typeId: null,
  zoneId: null,
  goLiveDate: "",
  description: "",
  operatorId: null,
  active: true,
  enabled: true,
}

const requiredText = (message: string) =>
  z.string().refine((value) => value.trim().length > 0, message)

const requiredChoice = (message: string) =>
  z
    .string()
    .nullable()
    .refine((value) => Boolean(value), message)

const comparableCode = (code: string) => code.trim().toLowerCase()

type FacilitySchemaOptions = {
  /** Other facilities' codes, and any the server refused, turned down as this one's. */
  takenCodes?: readonly string[]
  /** A saved facility must keep an operational date. */
  goLiveDateRequired?: boolean
  /** Managed by another system: its name and code cannot change, so they are not checked. */
  locked?: boolean
}

export function facilityFormSchema({
  takenCodes = [],
  goLiveDateRequired = false,
  locked = false,
}: FacilitySchemaOptions = {}) {
  const taken = new Set(takenCodes.map(comparableCode))
  return z.object({
    name: locked ? z.string() : requiredText("Enter a name."),
    code: locked
      ? z.string()
      : requiredText("Enter a code.").refine(
          (code) => !taken.has(comparableCode(code)),
          "Another facility already has this code."
        ),
    typeId: requiredChoice("Choose a facility type."),
    zoneId: requiredChoice("Choose a geographic zone."),
    goLiveDate: goLiveDateRequired
      ? requiredText("Choose an operational date.")
      : z.string(),
    description: z.string(),
    operatorId: z.string().nullable(),
    active: z.boolean(),
    enabled: z.boolean(),
  })
}

/** The values as a save sends them: text trimmed. */
export const toFacilityValues = (values: FacilityValues): FacilityValues => ({
  ...values,
  name: values.name.trim(),
  code: values.code.trim(),
  description: values.description.trim(),
})

/** How many fields differ from the saved facility. */
export function facilityChanges(values: FacilityValues, saved: FacilityValues) {
  return (Object.keys(saved) as (keyof FacilityValues)[]).filter((key) => {
    const value = values[key]
    const before = saved[key]
    return typeof value === "string" && typeof before === "string"
      ? value.trim() !== before.trim()
      : value !== before
  }).length
}

/** Options as a combobox lists them, by name. */
export const toFacilityItems = (options: readonly FacilityOption[]) =>
  options
    .map((option) => ({
      value: option.id,
      label: option.name,
      ...(option.description && { description: option.description }),
    }))
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts the new array without requiring ES2023
    .sort((a, b) => a.label.localeCompare(b.label))

"use client"

import { revalidateLogic, useStore } from "@tanstack/react-form"
import { useEffect, useId, useMemo, useRef } from "react"

import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import { FieldSkeleton } from "@/components/openlmis/form-fields/form-fields"

import {
  facilityChanges,
  facilityFormSchema,
  type FacilityValues,
  toFacilityValues,
} from "@/components/openlmis/facility-editor-page/facility-form"
import {
  type FacilityLookups,
  FacilityFormFields,
} from "@/components/openlmis/facility-editor-page/facility-form-fields"

type FacilityGeneralFormProps = {
  /** The facility's saved values, or `EMPTY_FACILITY` to add one; a skeleton shows until it is set. */
  facility: FacilityValues | undefined
  /** The types, zones and operators to pick from; their fields show skeletons until set. */
  lookups: FacilityLookups | undefined
  /** Other facilities' codes, and any the server refused, turned down as this one's. */
  takenCodes?: readonly string[]
  /** A saved facility must keep its operational date. */
  goLiveDateRequired?: boolean
  /** Managed by another system: name, code, zone, description and Active cannot change. */
  locked?: boolean
  readOnly?: boolean
  /** The form's id, for a Save placed elsewhere, e.g. in a page's `WorkspaceFooter`. */
  formId?: string
  /** Called with trimmed values once every field is valid. */
  onSubmit: (values: FacilityValues) => void
  /** Called when a submit finds errors, e.g. to open the tab that holds them. */
  onInvalid?: () => void
  /** Tells the page how many fields are unsaved, e.g. to ask before leaving. */
  onChangesChange?: (changes: number) => void
}

/** A facility's Information tab: name, code, type, zone, dates and status. */
export function FacilityGeneralForm({
  facility,
  lookups,
  ...props
}: FacilityGeneralFormProps) {
  if (!facility || !lookups) {
    return (
      <FacilityGeneralFormSkeleton
        goLiveDateRequired={props.goLiveDateRequired}
      />
    )
  }
  return <GeneralForm facility={facility} lookups={lookups} {...props} />
}

function GeneralForm({
  facility,
  lookups,
  takenCodes,
  goLiveDateRequired = false,
  locked = false,
  readOnly = false,
  formId: givenFormId,
  onSubmit,
  onInvalid,
  onChangesChange,
}: FacilityGeneralFormProps & {
  facility: FacilityValues
  lookups: FacilityLookups
}) {
  const generatedFormId = useId()
  const formId = givenFormId ?? generatedFormId
  // Keyed on the codes, so an inline array does not re-run validation each render.
  const takenKey = takenCodes?.join("\n") ?? ""
  const schema = useMemo(
    () =>
      facilityFormSchema({
        takenCodes: takenKey ? takenKey.split("\n") : [],
        goLiveDateRequired,
        locked,
      }),
    [takenKey, goLiveDateRequired, locked]
  )

  const form = useAppForm({
    defaultValues: facility,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => onSubmit(toFacilityValues(value)),
    onSubmitInvalid: () => onInvalid?.(),
  })
  const changes = useStore(form.store, (state) =>
    facilityChanges(state.values, facility)
  )

  // Starts again only when the values differ, so an equal new object keeps the draft.
  const facilityKey = JSON.stringify(facility)
  const resetKey = useRef(facilityKey)
  useEffect(() => {
    if (resetKey.current === facilityKey) return
    resetKey.current = facilityKey
    form.reset(facility)
  }, [form, facility, facilityKey])
  // A code the server refused shows its error at once, rather than on the next submit.
  useEffect(() => {
    if (form.state.submissionAttempts === 0) return
    form.update({ ...form.options, validators: { onDynamic: schema } })
    void form.validate("change")
  }, [form, schema])
  useEffect(() => {
    onChangesChange?.(changes)
  }, [changes, onChangesChange])

  return (
    <form
      id={formId}
      noValidate
      onSubmit={(event) => {
        event.preventDefault()
        void form.handleSubmit()
      }}
    >
      <FieldGroup>
        <FacilityFormFields
          form={form}
          goLiveDateRequired={goLiveDateRequired}
          locked={locked}
          lookups={lookups}
          readOnly={readOnly}
        />
      </FieldGroup>
    </form>
  )
}

