  addProgramSchema,
  availablePrograms,
  EMPTY_ADD_PROGRAM,
  type FacilityProgram,
  type ProgramOption,
  programName,
  toFacilityProgram,
} from "@/components/openlmis/facility-editor-page/facility-program"

type FacilityProgramDialogProps = {
  open: boolean
  /** The facility's rows, so only programs it does not support yet are offered. */
  rows: readonly FacilityProgram[]
  /** Every program; the form shows a skeleton until they are set. */
  programs: readonly ProgramOption[] | undefined
  /** Called with the new row; add it, then close. */
  onAdd: (row: FacilityProgram) => void
  onClose: () => void
}

/** Add Program: a program the facility supports, and the date it starts. */
export function FacilityProgramDialog({
  open,
  onClose,
  ...props
}: FacilityProgramDialogProps) {
  const { shown, dialogProps } = useDialogTarget(open || undefined, onClose)

  return (
    <FormDialog {...dialogProps()}>
      {shown && <AddProgramContent {...props} />}
    </FormDialog>
  )
}

function AddProgramHeader() {
  return (
    <FormDialogHeader>
      <FormDialogTitle>Add Program</FormDialogTitle>
      <FormDialogDescription>
        Choose a program this facility supports, and the date it starts.
      </FormDialogDescription>
    </FormDialogHeader>
  )
}

function AddProgramContent({
  programs,
  ...props
}: Omit<FacilityProgramDialogProps, "open" | "onClose">) {
  if (!programs) {
    return (
      <>
        <AddProgramHeader />
        <FormDialogBody>
          <div aria-busy>
            <FieldGroup>
              <FieldSkeleton label="Program" required />
              <FieldSkeleton label="Start Date" required />
            </FieldGroup>
          </div>
        </FormDialogBody>
        <FormDialogFooter>
          <FormDialogCancel />
          <FormDialogSubmit disabled>Add</FormDialogSubmit>
        </FormDialogFooter>
      </>
    )
  }
  return <AddProgramForm programs={programs} {...props} />
}

function AddProgramForm({
  rows,
  programs,
  onAdd,
}: Omit<FacilityProgramDialogProps, "open" | "onClose" | "programs"> & {
  programs: readonly ProgramOption[]
}) {
  // The choices as the dialog opened, so the program just added never drops out while it closes.
  const [rowsAtOpen] = useState(rows)
  const items = useMemo(
    () =>
      availablePrograms(programs, rowsAtOpen).map((program) => ({
        value: program.id,
        label: programName(program),
      })),
    [programs, rowsAtOpen]
  )

  const form = useAppForm({
    defaultValues: EMPTY_ADD_PROGRAM,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: addProgramSchema },
    onSubmit: ({ value }) => {
      const program = programs.find((item) => item.id === value.programId)
      if (program) onAdd(toFacilityProgram(program, value.startDate))
    },
  })

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <AddProgramHeader />
      <FormDialogBody>
        <FieldGroup>
          <form.AppField name="programId">
            {(field) => (
              <field.ComboboxField
                clearLabel="Clear Program"
                emptyMessage="No Matches"
                items={items}
                label="Program"
                placeholder="Select A Program"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="startDate">
            {(field) => (
              <field.DateField
                description="The program start date determines the first date available for users to enter requisitions related to the program."
                label="Start Date"
                placeholder="Pick A Date"
                required
              />
            )}
          </form.AppField>
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <FormDialogSubmit>Add</FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

import { z } from "zod"

/** A program a facility can support. */
export type ProgramOption = {
  id: string
  code: string
  name: string | null
}

/** A program the facility supports, and how. */
export type FacilityProgram = ProgramOption & {
  supportActive: boolean
  supportLocallyFulfilled: boolean
  /** `yyyy-MM-dd`, or empty when a legacy record has none. */
  supportStartDate: string
  /** Already stored: it cannot be removed here, and may lack a start date. */
  saved: boolean
}

/** The name a program is shown by: its name, or its code when it has none. */
export const programName = (program: Pick<ProgramOption, "code" | "name">) =>
  program.name || program.code

export const addProgramSchema = z.object({
  programId: z
    .string()
    .nullable()
    .refine((value) => Boolean(value), "Choose a program."),
  startDate: z
    .string()
    .refine((value) => value.length > 0, "Choose a start date."),
})

export type AddProgramValues = z.input<typeof addProgramSchema>

export const EMPTY_ADD_PROGRAM: AddProgramValues = {
  programId: null,
  startDate: "",
}

/** A new row for `program`: active, not locally fulfilled, from `startDate`. */
export const toFacilityProgram = (
  program: ProgramOption,
  startDate: string
): FacilityProgram => ({
  ...program,
  supportActive: true,
  supportLocallyFulfilled: false,
  supportStartDate: startDate,
  saved: false,
})

/** Programs the facility does not support yet, by name. */
export function availablePrograms(
  programs: readonly ProgramOption[],
  rows: readonly FacilityProgram[]
) {
  const added = new Set(rows.map((row) => row.id))
  return (
    programs
      .filter((program) => !added.has(program.id))
      // oxlint-disable-next-line unicorn/no-array-sort -- sorts the filtered array without requiring ES2023
      .sort((a, b) => programName(a).localeCompare(programName(b)))
  )
}

/** Legacy stored some programs without a start date; only a new row must have one. */
export const missingStartDate = (row: FacilityProgram) =>
  !row.saved && !row.supportStartDate

